const input = $input.first().json;
const timestamp = new Date().toLocaleString("es-CO", { timeZone: "America/Bogota", day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" });
const resumen = "Nuevo lead requiere atencion:\n\nLead: " + input.nombre + " | " + input.numero + "\nMotivo escalacion: " + input.motivo + "\nHora: " + timestamp + "\n\nContactar lo antes posible";
return [{
  json: {
    url: "https://evolution.srv1398596.hstgr.cloud/message/sendText/" + input.evolution_instance,
    header_name: "apikey",
    header_value: input.evolution_api_key,
    body: JSON.stringify({ number: input.wa_staff_numero, text: resumen }),
    numero: input.numero,
    nombre: input.nombre,
    evolution_instance: input.evolution_instance,
    evolution_api_key: input.evolution_api_key
  }
}];

const prev = $("Preparar notificacion staff").first().json;
return [{
  json: {
    url: "https://evolution.srv1398596.hstgr.cloud/message/sendText/" + prev.evolution_instance,
    header_name: "apikey",
    header_value: prev.evolution_api_key,
    body: JSON.stringify({ number: prev.numero, text: "Hola " + prev.nombre + "! En este momento voy a conectarte con una de nuestras asesoras especializadas, ella te contacta en los proximos minutos. Gracias por tu paciencia!" })
  }
}];

